import subprocess
import sys


def test_condefects_0():
    proc = subprocess.run(
        [sys.executable, "buggy.py"],
        input='4\n1\n2\n5\n998244353\n',
        capture_output=True,
        text=True,
        timeout=10,
    )
    expected = '1\n4\n17\n727512986\n'
    actual = proc.stdout.strip()
    assert actual == expected.strip(), (
        f"Expected {expected.strip()!r}, got {actual!r}"
    )


